"""OCR receipt extraction: date (ISO) and total_amount (string, 2dp)."""
import os
import re
import sys
from pathlib import Path

import pytesseract
from PIL import Image, ImageFilter, ImageOps
from openpyxl import Workbook

IMG_DIR = Path("/app/workspace/dataset/img")
OUT_XLSX = Path("/app/workspace/stat_ocr.xlsx")

TOTAL_TIERS = [
    [r"GRAND\s*TOTAL"],
    [r"TOTAL\s*RM", r"TOTAL\s*:\s*RM"],
    [r"TOTAL\s*AMOUNT"],
    [r"TOTAL\s*DUE", r"AMOUNT\s*DUE", r"BALANCE\s*DUE",
     r"NETT?\s*TOTAL", r"TOTAL", r"AMOUNT"],
]

EXCLUSION_RE = re.compile(
    r"SUBTOTAL|SUB\s*TOTAL|TAX|GST|SST|DISCOUNT|CHANGE|CASH\s*TENDERED"
)

PAYMENT_RE = re.compile(
    r"\b(CASH|CASH\s*RECEIVED|CASH\s*TENDERED|TENDERED|PAYMENT|PAID|"
    r"RECEIVED|CHANGE|VISA|MASTERCARD|MASTER|CARD|CREDIT|DEBIT)\b"
)

HEADER_COLS_RE = re.compile(
    r"DESCRIPTION|\bITEM\b|\bQTY\b|U\.?\s*PRICE|UNIT\s*PRICE|\bPRICE\b"
)

SUMMARY_CUTOFF_RE = re.compile(
    r"GST\s*SUMMARY|TAX\s*SUMMARY|SST\s*SUMMARY|"
    r"Amount\s*\(RM\)\s*Tax\s*\(RM\)|Tax\s*Code",
    re.IGNORECASE,
)

MONEY_RE = re.compile(r"(?<![\w.])(\d{1,3}(?:,\d{3})+\.\d{2}|\d+\.\d{2})(?![\w.])")

CONFUSABLES = str.maketrans({"O": "0", "o": "0", "Q": "0",
                              "l": "1", "I": "1", "|": "1",
                              "S": "5", "B": "8", "Z": "2",
                              "u": "0", "G": "6"})


def canon(line: str) -> str:
    return re.sub(r"\s+", " ", line.upper()).strip(" :.-")


def parse_money(line: str):
    m = MONEY_RE.findall(line)
    if not m:
        return None
    return m[-1].replace(",", "")


def parse_money_with_fix(line: str):
    v = parse_money(line)
    if v is not None:
        return v
    # Try confusable substitution inside numeric-ish tokens
    # Find tokens that look numeric with letter corruption
    tokens = re.findall(r"[\d.,OoQlI|SBZuG]+", line)
    for tok in tokens:
        if sum(c.isdigit() for c in tok) < 2:
            continue
        fixed = tok.translate(CONFUSABLES)
        m = MONEY_RE.search(" " + fixed + " ")
        if m:
            return m.group(1).replace(",", "")
    return None


def find_summary_cutoff(lines):
    for i, ln in enumerate(lines):
        if SUMMARY_CUTOFF_RE.search(ln):
            return i
    return len(lines)


def extract_total(lines):
    if not lines:
        return None
    cutoff = find_summary_cutoff(lines)
    canons = [canon(l) for l in lines]

    for tier in TOTAL_TIERS:
        tier_re = re.compile("|".join(tier))
        # Collect candidate indices
        candidates = []
        for i in range(min(len(lines), cutoff)):
            c = canons[i]
            if not c:
                continue
            if not tier_re.search(c):
                continue
            if EXCLUSION_RE.search(c):
                continue
            if HEADER_COLS_RE.search(c):
                continue
            candidates.append(i)
        # Iterate from last to first
        for i in reversed(candidates):
            v = parse_money_with_fix(lines[i])
            if v is not None:
                return v
            # Guarded fallback: keyword line has NO digits => check next line
            if not any(ch.isdigit() for ch in lines[i]):
                for j in range(i + 1, min(len(lines), cutoff)):
                    nxt = lines[j].strip()
                    if not nxt:
                        continue
                    cn = canons[j]
                    if EXCLUSION_RE.search(cn):
                        break
                    if PAYMENT_RE.search(cn):
                        break
                    v2 = parse_money_with_fix(nxt)
                    if v2 is not None:
                        return v2
                    break
    return None


# -------- Date extraction --------
DATE_LABEL_RE = re.compile(r"\b(DATE|DATA|DAIE|INVOICE\s*DATE)\b")
BAD_DATE_LABEL_RE = re.compile(r"PRINT|CLOSED|CLOSING|FRN|LOYALTY|PROMO|EXPIR")

DATE_PATTERNS = [
    # DD/MM/YYYY or DD-MM-YYYY or DD.MM.YYYY
    re.compile(r"\b(\d{1,2})[\-/.](\d{1,2})[\-/.](\d{2,4})\b"),
    # YYYY-MM-DD
    re.compile(r"\b(\d{4})[\-/.](\d{1,2})[\-/.](\d{1,2})\b"),
]

MONTH_NAMES = {
    "JAN": 1, "FEB": 2, "MAR": 3, "APR": 4, "MAY": 5, "JUN": 6,
    "JUL": 7, "AUG": 8, "SEP": 9, "SEPT": 9, "OCT": 10, "NOV": 11, "DEC": 12,
}
MONTH_RE = re.compile(
    r"\b(\d{1,2})[\-/\s]+(JAN|FEB|MAR|APR|MAY|JUN|JUL|AUG|SEP|SEPT|OCT|NOV|DEC)[A-Z]*[\-/\s,]+(\d{2,4})\b",
    re.IGNORECASE,
)


def valid_date(y, m, d):
    try:
        import datetime
        if y < 100:
            y += 2000 if y < 70 else 1900
        datetime.date(y, m, d)
        return (y, m, d)
    except Exception:
        return None


def iso(y, m, d):
    return f"{y:04d}-{m:02d}-{d:02d}"


def extract_date(lines, raw_text):
    candidates = []  # list of (score, (y,m,d))

    for idx, line in enumerate(lines):
        up = line.upper()
        has_label = bool(DATE_LABEL_RE.search(up)) and not BAD_DATE_LABEL_RE.search(up)
        bad_label = bool(BAD_DATE_LABEL_RE.search(up))

        # Month name pattern
        for m in MONTH_RE.finditer(line):
            d, mon_str, y = m.group(1), m.group(2).upper()[:3], m.group(3)
            if mon_str == "SEP" and m.group(2).upper().startswith("SEPT"):
                mon_str = "SEP"
            mon = MONTH_NAMES.get(mon_str)
            if mon is None:
                continue
            v = valid_date(int(y), mon, int(d))
            if v:
                score = (2 if has_label else 0) - (3 if bad_label else 0)
                candidates.append((score, v))

        # Numeric patterns
        for pat in DATE_PATTERNS:
            for m in pat.finditer(line):
                a, b, c = m.group(1), m.group(2), m.group(3)
                # YYYY-MM-DD vs DD-MM-YYYY
                if len(a) == 4:
                    v = valid_date(int(a), int(b), int(c))
                    if v:
                        score = (2 if has_label else 0) - (3 if bad_label else 0)
                        candidates.append((score, v))
                else:
                    # Try DD/MM/YYYY (Malaysian locale)
                    y = int(c)
                    d, mo = int(a), int(b)
                    v1 = valid_date(y, mo, d)  # DD/MM/YYYY
                    v2 = valid_date(y, d, mo)  # MM/DD/YYYY
                    # Prefer DD/MM
                    chosen = v1 or v2
                    if chosen:
                        score = (2 if has_label else 0) - (3 if bad_label else 0)
                        # If month > 12 was tried, v1 fails but v2 may succeed as MM/DD
                        candidates.append((score, chosen))

    if not candidates:
        return None

    # Pick highest score; ties -> earliest in text (first)
    candidates.sort(key=lambda x: -x[0])
    best_score = candidates[0][0]
    best = [c for c in candidates if c[0] == best_score][0][1]
    return iso(*best)


# -------- OCR --------
def ocr_variants(path):
    img = Image.open(path)
    gray = ImageOps.grayscale(img)
    variants = [
        ImageOps.autocontrast(gray),
        ImageOps.autocontrast(gray).resize(
            (gray.width * 2, gray.height * 2), Image.LANCZOS),
    ]
    texts = []
    for v in variants:
        for psm in ("--psm 6", "--psm 4"):
            try:
                t = pytesseract.image_to_string(v, config=psm)
                if t.strip():
                    texts.append(t)
            except Exception:
                pass
    return texts


def process(path):
    texts = ocr_variants(path)

    # Pick best total/date across variants
    totals = []
    dates = []
    for t in texts:
        lines = [l for l in t.splitlines() if l.strip()]
        tot = extract_total(lines)
        if tot:
            totals.append(tot)
        dt = extract_date(lines, t)
        if dt:
            dates.append(dt)

    total = None
    if totals:
        # Pick most common; tie-break first
        from collections import Counter
        total = Counter(totals).most_common(1)[0][0]
        # Format with two decimals
        try:
            total = f"{float(total):.2f}"
        except Exception:
            pass

    date = None
    if dates:
        from collections import Counter
        date = Counter(dates).most_common(1)[0][0]

    return date, total


def main():
    files = sorted(f for f in os.listdir(IMG_DIR)
                   if f.lower().endswith((".jpg", ".jpeg", ".png")))

    rows = []
    for f in files:
        path = IMG_DIR / f
        date, total = process(path)
        rows.append((f, date, total))
        print(f"{f}\tdate={date}\ttotal={total}", flush=True)

    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])
    for f, d, t in rows:
        ws.append([f, d if d is not None else None,
                   t if t is not None else None])
    wb.save(OUT_XLSX)
    print(f"Wrote {OUT_XLSX} with {len(rows)} rows")


if __name__ == "__main__":
    main()
